@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
@Import(ConsumerCareIntegrationTests.Fixtures.class)
class ConsumerCareIntegrationTests {
 static final EmbeddedPostgres PG;
 static {try{PG=EmbeddedPostgres.builder().setPort(0).start();}catch(Exception e){throw new ExceptionInInitializerError(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->PG.getJdbcUrl("postgres","postgres"));r.add("spring.datasource.username",()->"postgres");r.add("spring.datasource.password",()->"postgres");r.add("pawday.auth.secret-key",()->"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=");r.add("management.health.redis.enabled",()->false);r.add("management.health.rabbit.enabled",()->false);r.add("pawday.outbox.workers-enabled",()->false);r.add("pawday.outbox.consumer-enabled",()->false);r.add("pawday.search.enabled",()->false);r.add("pawday.care.workers-enabled",()->false);r.add("pawday.storage.cleanup-enabled",()->false);}
 @TestConfiguration static class Fixtures {@Bean @Primary Clock petClock(){return Clock.fixed(Instant.parse("2026-10-04T00:00:00Z"),ZoneId.of("Asia/Shanghai"));}}
 @Autowired cn.pawday.care.PetFoodService food; @Autowired cn.pawday.support.SupportInboxConsumer inbox;
 @Autowired JdbcTemplate db;@Autowired Crypto crypto;@Autowired Clock clock;@LocalServerPort int port;
 final JsonMapper json=JsonMapper.builder().build();final HttpClient http=HttpClient.newHttpClient();
 static final List<Map<String,Object>> SAMPLES=new CopyOnWriteArrayList<>();
 String tokenA,tokenB,adminToken;UUID userA,adminPrincipal,adminSession;
 static final String CAT="10000000-0000-4000-8000-000000000001",SMALL="10000000-0000-4000-8000-000000000005";
 record Response(int status,JsonNode body){JsonNode data(){return body.get("data");}String id(){return data().get("id").asString();}}
 String key(){return UUID.randomUUID().toString();}
 String consumer(){UUID user=UUID.randomUUID(),p=UUID.randomUUID();db.update("INSERT INTO app_user(id,status) VALUES (?,'ACTIVE')",user);db.update("INSERT INTO identity_principal(id,realm,user_id) VALUES (?,'CONSUMER',?)",p,user);userA=user;return session(p);}
 String session(UUID p){UUID s=UUID.randomUUID();String t=crypto.token();db.update("INSERT INTO auth_session(id,principal_id,access_token_hash,device_id,expires_at,refresh_expires_at,created_at) VALUES (?,?,?,'PET-IT',?,?,?)",s,p,crypto.hash(t),Timestamp.from(clock.instant().plusSeconds(900)),Timestamp.from(clock.instant().plusSeconds(2592000)),Timestamp.from(clock.instant()));adminSession=s;return t;}
 @BeforeEach void setup(){db.update("UPDATE pet_food_plans SET active=false WHERE active");tokenB=consumer();tokenA=consumer();adminPrincipal=UUID.randomUUID();db.update("INSERT INTO identity_principal(id,realm,login_name,password_hash) VALUES (?,'ADMIN',?,?)",adminPrincipal,key(),"TEST-ONLY");UUID role=UUID.randomUUID();db.update("INSERT INTO role(id,scope_type,code,name) VALUES (?,'ADMIN',?,'Pet test')",role,key());db.update("INSERT INTO role_permission(role_id,permission_id) SELECT ?,id FROM permission WHERE code IN ('pet.taxonomy.read','pet.taxonomy.write')",role);db.update("INSERT INTO principal_role(principal_id,role_id,realm) VALUES (?,?,'ADMIN')",adminPrincipal,role);adminToken=session(adminPrincipal);}
 String proof(){String p=crypto.token();db.update("INSERT INTO reverify_grant(token_hash,session_id,action,expires_at,created_at) VALUES (?,?,'pet.taxonomy.write',?,?)",crypto.hash(p),adminSession,Timestamp.from(clock.instant().plusSeconds(120)),Timestamp.from(clock.instant()));return p;}
 Response request(String method,String path,Object payload,String token,Map<String,String> headers){try{var b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1"+path)).timeout(Duration.ofSeconds(20));if(token!=null)b.header("Authorization","Bearer "+token);headers.forEach(b::header);if(payload==null)b.method(method,HttpRequest.BodyPublishers.noBody());else if(payload instanceof byte[] bytes)b.method(method,HttpRequest.BodyPublishers.ofByteArray(bytes));else b.header("Content-Type","application/json").method(method,HttpRequest.BodyPublishers.ofString(json.writeValueAsString(payload)));var response=http.send(b.build(),HttpResponse.BodyHandlers.ofString());var body=json.readTree(response.body());if(!path.startsWith("/media/"))SAMPLES.add(Map.of("method",method.toLowerCase(),"path",path,"status",response.statusCode(),"response",body));return new Response(response.statusCode(),body);}catch(Exception e){throw new AssertionError(e);}}
 Response req(String method,String path,Object b,String token){return request(method,path,b,token,Map.of("Idempotency-Key",key()));}
 Map<String,Object> pet(){return new LinkedHashMap<>(Map.of("name","小爪","species_id",CAT,"sex","UNKNOWN","neutered_status","UNKNOWN","allergens",List.of(),"avoidance_notes",List.of()));}
 Response create(){var r=req("POST","/consumer/pets",pet(),tokenA);assertEquals(201,r.status(),r.body().toString());return r;}
 Response admin(String type,Map<String,Object> b){return request("POST","/admin/pet-taxonomy/"+type,b,adminToken,Map.of("Idempotency-Key",key(),"X-Reverify-Token",proof()));}
 Map<String,Object> stage(String code,Integer min,Integer max,boolean unknown,String unit){Map<String,Object>d=new LinkedHashMap<>();d.put("stage_code",code);d.put("display_name",code);d.put("min_age_value",min);d.put("max_age_value",max);d.put("age_unit",unit);d.put("is_unknown",unknown);return d;}
 Response publish(List<Map<String,Object>> stages,List<String> sources){return admin("life-stage-rules",Map.of("species_id",CAT,"source_refs",sources,"stages",stages));}
 @AfterAll static void close() throws Exception{Files.createDirectories(Path.of("target"));Files.writeString(Path.of("target/m67-contract-samples.json"),JsonMapper.builder().build().writeValueAsString(SAMPLES));Files.writeString(Path.of("target/m67-schema.json"),JsonMapper.builder().build().writeValueAsString(new org.springframework.jdbc.core.JdbcTemplate(new org.springframework.jdbc.datasource.DriverManagerDataSource(PG.getJdbcUrl("postgres","postgres"),"postgres","postgres")).queryForList("SELECT table_name,column_name,ordinal_position,udt_name,is_nullable,character_maximum_length FROM information_schema.columns WHERE table_schema='public' AND table_name NOT IN ('flyway_schema_history','m63_fixture') ORDER BY table_name,ordinal_position")));PG.close();}

 Map<String,Object> foodBody(){var b=new LinkedHashMap<String,Object>(Map.of("food_name","TEST 粮","package_weight_g",1000,"daily_amount_g",100,"started_on","2026-10-01","reminder_enabled",true,"remind_before_days",7));b.put("sku_id",null);return b;}
 Map<String,String> headers(int v){return Map.of("If-Match","\""+v+"\"","Idempotency-Key",key());}
 String foodPath(){return "/consumer/pets/"+create().id()+"/food";}
 @Test void startEstimateCalibrateHistoryStop(){String path=foodPath();assertTrue(req("GET",path,null,tokenA).data().isNull());var made=request("PUT",path,foodBody(),tokenA,headers(0));assertEquals(200,made.status(),made.body().toString());assertEquals(700,made.data().get("estimated_remaining_g").asInt());assertEquals("2026-10-11",made.data().get("estimated_finish_on").asString());var cal=request("POST",path+"/calibrations",Map.of("remaining_g",250,"recorded_on","2026-10-04"),tokenA,headers(1));assertEquals(200,cal.status(),cal.body().toString());assertEquals("2026-10-07",cal.data().get("estimated_finish_on").asString());assertEquals(2,req("GET",path+"/history",null,tokenA).data().size());assertEquals(200,request("POST",path+"/stop",null,tokenA,headers(2)).status());assertFalse(req("GET",path,null,tokenA).data().get("active").asBoolean());assertEquals(0,food.enqueueDue());}
 @Test void unauthorizedAndForeignPlanCannotBeAccessed(){String path=foodPath();assertEquals(401,req("GET",path,null,null).status());assertEquals(403,req("GET",path,null,adminToken).status());assertEquals(404,req("GET",path,null,tokenB).status());assertEquals(404,request("PUT",path,foodBody(),tokenB,headers(0)).status());assertEquals(404,req("GET",path+"/history",null,tokenB).status());}
 @Test void replayAndConflictDoNotDuplicateFacts(){String path=foodPath();var h=headers(0);var a=request("PUT",path,foodBody(),tokenA,h);assertEquals(200,a.status());assertEquals(a.data(),request("PUT",path,foodBody(),tokenA,h).data());var changed=foodBody();changed.put("daily_amount_g",200);assertEquals(409,request("PUT",path,changed,tokenA,h).status());assertEquals(409,request("PUT",path,foodBody(),tokenA,headers(0)).status());assertEquals(1,req("GET",path+"/history",null,tokenA).data().size());}
 @Test void invalidInputsAndCalibrationRejected(){String path=foodPath();var b=foodBody();b.put("started_on","2027-01-01");assertEquals(400,request("PUT",path,b,tokenA,headers(0)).status());b=foodBody();b.put("daily_amount_g",0);assertEquals(400,request("PUT",path,b,tokenA,headers(0)).status());assertEquals(400,req("PUT",path,foodBody(),tokenA).status());assertEquals(200,request("PUT",path,foodBody(),tokenA,headers(0)).status());assertEquals(400,request("POST",path+"/calibrations",Map.of("remaining_g",1001,"recorded_on","2026-10-04"),tokenA,headers(1)).status());assertEquals(400,request("POST",path+"/calibrations",Map.of("remaining_g",10,"recorded_on","2026-09-30"),tokenA,headers(1)).status());}
 @Test void auditFailureRollsBackFoodHistoryAndCommand(){String path=foodPath(),k=key();db.execute("CREATE FUNCTION fail_food_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='pet.food.start' THEN RAISE EXCEPTION 'TEST_ONLY'; END IF; RETURN NEW; END $$");db.execute("CREATE TRIGGER test_food_audit BEFORE INSERT ON audit_event FOR EACH ROW EXECUTE FUNCTION fail_food_audit()");try{assertEquals(503,request("PUT",path,foodBody(),tokenA,Map.of("If-Match","\"0\"","Idempotency-Key",k)).status());assertTrue(req("GET",path,null,tokenA).data().isNull());assertEquals(0,db.queryForObject("SELECT count(*) FROM identity_command WHERE idempotency_key=?",Integer.class,k));}finally{db.execute("DROP TRIGGER test_food_audit ON audit_event");db.execute("DROP FUNCTION fail_food_audit()");}}
 cn.pawday.outbox.EventEnvelope event(String plan){var row=db.queryForMap("SELECT o.* FROM pet_food_plans f JOIN outbox_event o ON o.id=f.emitted_event_id WHERE f.id=?",UUID.fromString(plan));return new cn.pawday.outbox.EventEnvelope((UUID)row.get("id"),"PetFoodReminderDue",1,"PET_FOOD_PLAN",plan,null,1,0,json.readValue(row.get("payload").toString(),Map.class));}
 @Test void twoWorkersAndDuplicateConsumerHaveOneReminder() throws Exception{String path=foodPath();var plan=request("PUT",path,foodBody(),tokenA,headers(0));assertEquals(200,plan.status());try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->food.enqueueDue());var b=pool.submit(()->food.enqueueDue());assertEquals(1,a.get()+b.get());}var e=event(plan.id());inbox.process(e);inbox.process(e);assertEquals(1,db.queryForObject("SELECT count(*) FROM notification_messages WHERE event_id=?",Integer.class,e.event_id()));var messages=req("GET","/consumer/messages?category=FOOD_REMINDER",null,tokenA);assertEquals(1,messages.data().size());String mid=messages.data().get(0).get("id").asString();assertTrue(req("GET","/consumer/messages/"+mid+"/target",null,tokenA).data().get("destination").asString().startsWith("/pet-food?pet_id="));assertEquals(404,req("GET","/consumer/messages/"+mid+"/target",null,tokenB).status());}
 @Test void supersededReminderIsIgnoredAndPreferenceHonored(){String path=foodPath();var made=request("PUT",path,foodBody(),tokenA,headers(0));food.enqueueDue();var old=event(made.id());assertEquals(200,request("POST",path+"/calibrations",Map.of("remaining_g",200,"recorded_on","2026-10-04"),tokenA,headers(1)).status());inbox.process(old);assertEquals(0,db.queryForObject("SELECT count(*) FROM notification_messages WHERE event_id=?",Integer.class,old.event_id()));assertEquals(200,req("PUT","/consumer/notification-preferences/FOOD_REMINDER",Map.of("enabled",false),tokenA).status());food.enqueueDue();var e=event(made.id());inbox.process(e);assertFalse(db.queryForObject("SELECT notify_enabled FROM notification_messages WHERE event_id=?",Boolean.class,e.event_id()));}
 UUID product(){UUID b=UUID.randomUUID(),p=UUID.randomUUID(),k=UUID.randomUUID();db.update("INSERT INTO brands(id,name,source_ref) VALUES (?,?,'TEST')",b,key());db.update("INSERT INTO spus(id,brand_id,name,pet_category,category) VALUES (?,?,'TEST 商品','CAT','DRY_FOOD')",p,b);db.update("INSERT INTO skus(id,spu_id,sku_code,weight_g,package_unit) VALUES (?,?,?,1000,'BAG')",k,p,key());db.update("INSERT INTO sku_standard_versions(id,sku_id,version_no,status,ingredients,nutrients,allergens_known,life_stage_ids,source_refs,source_updated_on,created_by,published_at) VALUES (?,?,1,'PUBLISHED','[]','[]',false,'[]','[\"TEST\"]','2026-10-01',?,clock_timestamp())",UUID.randomUUID(),k,adminPrincipal);return p;}
 @Test void favoriteRoundTripOwnershipAndUnavailable(){UUID p=product();var b=Map.of("kind","PRODUCT","target_id",p.toString());var saved=req("POST","/consumer/favorites",b,tokenA);assertEquals(200,saved.status(),saved.body().toString());assertEquals(saved.id(),req("POST","/consumer/favorites",b,tokenA).id());assertEquals(1,req("GET","/consumer/favorites",null,tokenA).data().size());assertEquals(0,req("GET","/consumer/favorites",null,tokenB).data().size());assertEquals(404,req("DELETE","/consumer/favorites/"+saved.id(),null,tokenB).status());db.update("UPDATE spus SET status='RETIRED' WHERE id=?",p);var unavailable=req("GET","/consumer/favorites",null,tokenA).data().get(0);assertFalse(unavailable.get("available").asBoolean());assertEquals("已不可用",unavailable.get("name").asString());assertEquals(200,req("DELETE","/consumer/favorites/"+saved.id(),null,tokenA).status());assertEquals(0,req("GET","/consumer/favorites",null,tokenA).data().size());}
 @Test void concurrentFavoriteSaveCreatesOneRow() throws Exception{UUID p=product();var b=Map.of("kind","PRODUCT","target_id",p.toString());try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->req("POST","/consumer/favorites",b,tokenA));var c=pool.submit(()->req("POST","/consumer/favorites",b,tokenA));assertEquals(a.get().id(),c.get().id());}assertEquals(1,db.queryForObject("SELECT count(*) FROM consumer_favorites WHERE user_id=? AND spu_id=?",Integer.class,userA,p));}
 @Test void storeFavoriteRequiresPublishedProfile(){UUID m=UUID.randomUUID(),s=UUID.randomUUID();db.update("INSERT INTO merchant(id,name,status) VALUES (?,'TEST','ACTIVE')",m);db.update("INSERT INTO merchant_store(id,merchant_id,name) VALUES (?,?,'TEST 门店')",s,m);var b=Map.of("kind","STORE","target_id",s.toString());assertEquals(404,req("POST","/consumer/favorites",b,tokenA).status());db.update("INSERT INTO nearby_store_profile(store_id,city,category,address,phone,business_hours,longitude,latitude,services,publication_status,claim_status) VALUES (?,'重庆','PET_STORE','TEST','TEST','TEST',106,29,'[]','PUBLISHED','VERIFIED')",s);assertEquals(200,req("POST","/consumer/favorites",b,tokenA).status());}
}
